// Speech helpers for voice mode. Listening uses the browser's SpeechRecognition (speech -> text;
// where the browser lacks it, voice mode isn't offered). Speaking uses either the device's own
// voices (speechSynthesis) or Piper voices generated by our server (/Assistant/api/tts), chosen in
// Settings and saved per browser.

const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
const VOICE_KEY = "voiceURI";
const ENGINE_KEY = "voiceEngine"; // "device" or "piper"
const PIPER_KEY = "piperVoice";
const SPEED_KEY = "voiceSpeed";
const LOOK_KEY = "voiceLook"; // voice-mode animation: "wave" or "orb"
export const MIN_SPEED = 0.75;
export const MAX_SPEED = 1.5;

export const recognitionSupported = Boolean(Recognition);
export const synthesisSupported = "speechSynthesis" in window;

// The microphone for a whole voice session: one continuous recognizer that stays on from open()
// to close(), like a phone call. Turning it off and on each turn made iOS stop delivering audio
// after a few turns. Words only count while listen() is waiting; anything heard while thinking or
// speaking (including the assistant's own voice) is ignored. If the browser ends the recognizer by
// itself, it's restarted right away. onFatal(message) reports errors that need the user (mic not
// allowed, or no mic); the mic stays off after one.
const PAUSE_MS = 1200; // this long after the last words, the utterance is done
const FATAL = new Set(["not-allowed", "service-not-allowed", "audio-capture"]);

export function openMic(onFatal) {
  let recognition = null;
  let closed = false;
  let results = []; // transcripts from the current recognizer, by result index
  let from = 0; // first result index that belongs to the current utterance
  let carried = ""; // words from the current utterance heard by an earlier recognizer
  let turn = null; // { onInterim, resolve } while listen() is waiting
  let pause = null;
  let startedAt = 0;

  const heard = () => [carried, ...results.slice(from)].join(" ").replace(/\s+/g, " ").trim();

  const finishTurn = () => {
    clearTimeout(pause);
    if (!turn) return;
    const { resolve } = turn;
    const text = heard();
    turn = null;
    resolve(text);
  };

  const start = () => {
    if (closed) return;
    const rec = new Recognition();
    recognition = rec;
    rec.lang = navigator.language || "en-US";
    rec.continuous = true;
    rec.interimResults = true;
    results = [];
    from = 0;
    startedAt = performance.now();
    rec.onresult = (event) => {
      for (let i = event.resultIndex; i < event.results.length; i++) results[i] = event.results[i][0].transcript;
      results.length = event.results.length;
      if (!turn) return;
      const text = heard();
      if (!text) return;
      turn.onInterim?.(text);
      clearTimeout(pause);
      pause = setTimeout(finishTurn, PAUSE_MS);
    };
    rec.onerror = (event) => {
      if (!FATAL.has(event.error)) return; // no-speech, aborted, network: onend restarts it
      closed = true;
      onFatal?.(errorMessage(event.error));
      finishTurn();
    };
    rec.onend = () => {
      if (recognition !== rec || closed) return;
      if (turn) carried = heard(); // keep words heard so far in this turn
      // Ended at once: wait a moment so a failing mic can't restart in a tight loop
      setTimeout(start, performance.now() - startedAt < 1000 ? 1000 : 0);
    };
    rec.start();
  };
  start();

  return {
    // Resolves with the next thing said, once the speaker pauses
    listen(onInterim) {
      finishTurn();
      if (closed) return Promise.resolve("");
      carried = "";
      from = results.length; // ignore everything heard before now
      return new Promise((resolve) => {
        turn = { onInterim, resolve };
      });
    },
    // End the current turn now with whatever was heard (tapping "done talking")
    finish: finishTurn,
    close() {
      closed = true;
      finishTurn();
      recognition?.abort();
    },
  };
}

function errorMessage(code) {
  if (code === "not-allowed" || code === "service-not-allowed") {
    return "Microphone or speech recognition isn't allowed. On iPhone, turn on Siri & Dictation and allow the microphone.";
  }
  if (code === "network") return "Speech recognition needs an internet connection.";
  if (code === "audio-capture") return "No microphone was found.";
  return `Speech recognition failed (${code}).`;
}

// Turns a Markdown reply into something pleasant to hear. Voice-mode replies are asked to be plain
// already, but tool results and older habits can still produce tables, code, or links.
export function speakable(markdown) {
  return markdown
    .replace(/```[\s\S]*?```/g, " (I've put the code in the chat.) ")
    .replace(/(^\|.*\|\s*$\n?)+/gm, " (The table is in the chat.) ")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/https?:\/\/\S+/g, "a link in the chat")
    .replace(/<[^>]+>/g, " ")
    .replace(/[*_`#>~]+/g, "")
    .replace(/^\s*[-•]\s+/gm, "")
    .replace(/\s+/g, " ")
    .trim();
}

export function englishVoices() {
  if (!synthesisSupported) return [];
  return speechSynthesis.getVoices().filter((v) => v.lang.toLowerCase().startsWith("en"));
}

function load(key) {
  try {
    return localStorage.getItem(key) || "";
  } catch {
    return "";
  }
}

function store(key, value) {
  try {
    if (value) localStorage.setItem(key, value);
    else localStorage.removeItem(key);
  } catch {
    // Storage unavailable (private mode): the choice just won't persist
  }
}

export const savedVoiceURI = () => load(VOICE_KEY);
export const saveVoiceURI = (uri) => store(VOICE_KEY, uri);
export const savedEngine = () => (load(ENGINE_KEY) === "piper" ? "piper" : "device");
export const saveEngine = (engine) => store(ENGINE_KEY, engine === "piper" ? "piper" : "");
export const savedPiperVoice = () => load(PIPER_KEY);
export const savePiperVoice = (id) => store(PIPER_KEY, id);
// Speaking speed, 1 = normal; applies to both device and Piper voices
export function savedSpeed() {
  const speed = parseFloat(load(SPEED_KEY));
  return Number.isFinite(speed) ? Math.min(MAX_SPEED, Math.max(MIN_SPEED, speed)) : 1;
}
export const saveSpeed = (speed) => store(SPEED_KEY, speed === 1 ? "" : String(speed));
export const savedLook = () => (load(LOOK_KEY) === "orb" ? "orb" : "wave");
export const saveLook = (look) => store(LOOK_KEY, look === "orb" ? "orb" : "");

// Piper voices installed on the server: [{ id, name }]
export async function piperVoices() {
  const res = await fetch("/Assistant/api/tts/voices");
  if (!res.ok) throw new Error(`Couldn't load server voices (${res.status})`);
  return (await res.json()).voices;
}

// The saved voice, else a British male voice for the Jarvis feel, else the browser default
function pickVoice() {
  const voices = englishVoices();
  const saved = savedVoiceURI();
  return (
    voices.find((v) => v.voiceURI === saved) ||
    voices.find((v) => /daniel|arthur|oliver|george/i.test(v.name) && v.lang === "en-GB") ||
    voices.find((v) => v.lang === "en-GB") ||
    null
  );
}

// Browsers load voices asynchronously, so getVoices() can be empty at first. Choosing a voice then
// falls back to the system default, and the next reply (voices loaded) switches to another voice
// mid-conversation. Wait for the list first (briefly; some browsers never fire the event).
let voicesReady = null;
function loadVoices() {
  if (!synthesisSupported || speechSynthesis.getVoices().length) return Promise.resolve();
  voicesReady ??= new Promise((resolve) => {
    const done = () => {
      speechSynthesis.removeEventListener("voiceschanged", done);
      resolve();
    };
    speechSynthesis.addEventListener("voiceschanged", done);
    setTimeout(done, 1500);
  });
  return voicesReady;
}
loadVoices();

// One audio element for Piper speech. iOS only plays audio started by a tap, but an element that
// has played once (the silent clip in unlockSpeech) may play again later without one.
const player = typeof Audio !== "undefined" ? new Audio() : null;
const SILENT_WAV = "data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=";
let finishPlayback = null; // resolves the current Piper speak() promise

// iOS only lets a page speak after a user gesture: call this from the tap that opens voice mode.
// Only the chosen voice source is unlocked, and audioSettled() waits for that silent clip to finish.
let unlocking = Promise.resolve();

export function unlockSpeech(engine = savedEngine()) {
  unlocking = new Promise((resolve) => {
    setTimeout(resolve, 600); // in case neither finishes cleanly
    if (engine === "piper" && player) {
      player.onended = () => resolve();
      player.src = SILENT_WAV;
      player.play().catch(() => resolve());
    } else if (synthesisSupported) {
      const silent = new SpeechSynthesisUtterance(" ");
      silent.volume = 0;
      silent.onend = () => resolve();
      silent.onerror = () => resolve();
      speechSynthesis.speak(silent);
    } else {
      resolve();
    }
  });
}

// Resolves once the unlock clip has finished, plus a short pause before the mic opens
export async function audioSettled() {
  await unlocking;
  await new Promise((resolve) => setTimeout(resolve, 300));
}

// Speaks the text with the voice chosen in Settings, or the given override; resolves when it
// finishes or is stopped. Piper failures (server down, voice removed) fall back to a device voice.
// onWord(i) is called with the index (in splitWords(text)) of the word being spoken, for
// highlighting: exact for device voices that report word boundaries, estimated otherwise.
export async function speak(text, {
  engine = savedEngine(), voiceURI, piperVoice = savedPiperVoice(), speed = savedSpeed(), onWord,
} = {}) {
  if (!text) return;
  if (engine === "piper" && piperVoice && player) {
    const { rest, fromWord } = await speakWithPiper(text, piperVoice, speed, onWord);
    if (!rest) return;
    // Piper failed partway (or at the start): say the rest with a device voice, without repeating
    return speakOnDevice(rest, voiceURI, speed, onWord, fromWord);
  }
  return speakOnDevice(text, voiceURI, speed, onWord, 0);
}

// The words of a text, the way speech highlighting counts them
export const splitWords = (text) => text.split(/\s+/).filter(Boolean);

// Which word is playing, `progress` (0-1) of the way through some audio: longer words take longer
function wordAt(words, progress) {
  const weights = words.map((w) => w.length + 1);
  const target = progress * weights.reduce((a, b) => a + b, 0);
  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    sum += weights[i];
    if (sum > target) return i;
  }
  return words.length - 1;
}

// Splits text into sentence-sized pieces (about `max` characters), so speech can start after the
// first one is generated instead of after the whole reply. The first piece is kept shorter
// (`firstMax`): its generation time is the wait before the first word; later pieces are generated
// while earlier ones play.
export function chunkText(text, max = 220, firstMax = 120) {
  if (text.trim().length <= firstMax) return [text.trim()]; // short replies: one request
  const sentences = text.match(/[^.!?]+[.!?]+["')\]]*\s*|[^.!?]+$/g) || [text];
  const chunks = [];
  for (let sentence of sentences.map((x) => x.trim()).filter(Boolean)) {
    const limit = () => (chunks.length ? max : firstMax);
    while (sentence.length > limit()) {
      const lim = limit();
      // An overlong sentence: break at the last comma or space before the limit
      const cut = Math.max(sentence.lastIndexOf(", ", lim), sentence.lastIndexOf(" ", lim));
      const at = cut > lim / 2 ? cut + 1 : lim;
      chunks.push(sentence.slice(0, at).trim());
      sentence = sentence.slice(at).trim();
    }
    const last = chunks[chunks.length - 1];
    // Never grow the first piece: it should be ready as soon as possible
    if (last && chunks.length > 1 && last.length + sentence.length + 1 <= max) chunks[chunks.length - 1] = `${last} ${sentence}`;
    else if (sentence) chunks.push(sentence);
  }
  return chunks;
}

let speechRun = 0; // bumped by stopSpeaking() so an in-progress Piper run stops between chunks

async function fetchPiperAudio(text, voice, speed) {
  const res = await fetch("/Assistant/api/tts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text, voice, speed }),
  });
  if (!res.ok) throw new Error(`server speech failed (${res.status})`);
  return URL.createObjectURL(await res.blob());
}

// Plays one clip; onProgress(0-1) is called every animation frame while it plays
function play(url, onProgress) {
  let frame = null;
  const tick = () => {
    if (player.duration && Number.isFinite(player.duration)) onProgress?.(player.currentTime / player.duration);
    frame = requestAnimationFrame(tick);
  };
  return new Promise((resolve, reject) => {
    finishPlayback = resolve;
    player.onended = () => resolve();
    player.onerror = () => reject(new Error("audio playback failed"));
    player.src = url;
    player.play().then(() => {
      frame = requestAnimationFrame(tick);
    }, reject);
  }).finally(() => cancelAnimationFrame(frame));
}

// A prefetched chunk that won't be played: release its audio and ignore its errors
function discard(pending) {
  pending?.then((url) => URL.revokeObjectURL(url), () => {});
}

// Generates and plays the text chunk by chunk, fetching the next chunk while the current one plays.
// Returns "" when done (or stopped), or the text that couldn't be spoken if Piper failed.
// Returns { rest: "", ... } when done or stopped; if Piper failed, rest is the unspoken text and
// fromWord the index of its first word in the full text (so highlighting carries on correctly).
async function speakWithPiper(text, voice, speed, onWord) {
  const run = ++speechRun;
  const chunks = chunkText(text.slice(0, 6000));
  const chunkWords = chunks.map(splitWords);
  const firstWord = chunkWords.map((_, i) => chunkWords.slice(0, i).reduce((n, w) => n + w.length, 0));
  const failed = (i) => (run === speechRun ? { rest: chunks.slice(i).join(" "), fromWord: firstWord[i] } : { rest: "" });
  let next = fetchPiperAudio(chunks[0], voice, speed);
  for (let i = 0; i < chunks.length; i++) {
    let url;
    try {
      url = await next;
    } catch (e) {
      console.warn("Piper speech failed; using a device voice for the rest:", e);
      return failed(i);
    }
    if (run !== speechRun) {
      URL.revokeObjectURL(url);
      return { rest: "" };
    }
    next = i + 1 < chunks.length ? fetchPiperAudio(chunks[i + 1], voice, speed) : null;
    try {
      // Piper gives no word timings: estimate the word from how far through this chunk's audio we are
      await play(url, (progress) => onWord?.(firstWord[i] + wordAt(chunkWords[i], progress)));
    } catch (e) {
      console.warn("Piper audio playback failed; using a device voice for the rest:", e);
      discard(next);
      return failed(i);
    } finally {
      finishPlayback = null;
      URL.revokeObjectURL(url);
    }
    if (run !== speechRun) {
      discard(next);
      return { rest: "" };
    }
  }
  return { rest: "" };
}

const WORDS_PER_SECOND = 2.7; // typical speaking pace, for voices that don't report word boundaries

// fromWord: index in the full text of this text's first word (non-zero after a Piper fallback)
async function speakOnDevice(text, voiceURI, speed = 1, onWord, fromWord = 0) {
  if (!synthesisSupported) return;
  await loadVoices();
  // Character offset where each word starts, to turn boundary events into word indexes
  const starts = [...text.matchAll(/\S+/g)].map((m) => m.index);
  let estimate = null;
  return new Promise((resolve) => {
    speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voice = voiceURI ? englishVoices().find((v) => v.voiceURI === voiceURI) : pickVoice();
    if (voice) {
      utterance.voice = voice;
      utterance.lang = voice.lang;
    }
    utterance.rate = 1.05 * speed; // 1.05: device voices sound a little slow at their default
    let reported = false;
    utterance.onboundary = (event) => {
      if (event.name && event.name !== "word") return;
      reported = true;
      clearInterval(estimate);
      let i = 0;
      while (i + 1 < starts.length && starts[i + 1] <= event.charIndex) i++;
      onWord?.(fromWord + i);
    };
    utterance.onstart = () => {
      onWord?.(fromWord);
      // Some voices never report boundaries: estimate from a typical pace instead
      const began = performance.now();
      estimate = setInterval(() => {
        if (reported) return clearInterval(estimate);
        const elapsed = (performance.now() - began) / 1000;
        if (elapsed < 0.7) return;
        onWord?.(fromWord + Math.min(starts.length - 1, Math.floor(elapsed * WORDS_PER_SECOND * utterance.rate)));
      }, 100);
    };
    const finish = () => {
      clearInterval(estimate);
      resolve();
    };
    utterance.onend = finish;
    utterance.onerror = finish;
    speechSynthesis.speak(utterance);
  });
}

export function stopSpeaking() {
  speechRun++; // stops a chunked Piper run before its next chunk
  if (synthesisSupported) speechSynthesis.cancel();
  if (player && !player.paused) player.pause();
  finishPlayback?.(); // pausing doesn't fire "ended", so finish the pending speak() ourselves
}
